-- Generic local-only fixtures; no document/PDF is created by the import itself.
RESET ROLE;
CREATE FUNCTION test.manual_definition21(p_code text DEFAULT 'IMPORT-TEST',p_count integer DEFAULT 1) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT test.template_definition20()||jsonb_build_object('code',p_code,'name','Minuta genérica para revisão','content',string_agg('{{documento.campo_'||n||'}}',' ' ORDER BY n),'variables',jsonb_agg(jsonb_build_object('key','documento.campo_'||n,'label','Campo '||n,'type','text','required',true) ORDER BY n)) FROM generate_series(1,p_count)n;
$$;
GRANT EXECUTE ON FUNCTION test.manual_definition21(text,integer) TO migrator;
SELECT test.assert_true(private.templates_validate20(test.manual_definition21())=test.manual_definition21(),'pós21: declared manual key with underscore accepted');
SELECT test.assert_true(private.templates_validate20(test.manual_definition21('LIMIT-80',80))=test.manual_definition21('LIMIT-80',80),'pós21: exactly80 manual variables accepted');
SELECT test.expect_error($q$SELECT private.templates_validate20(test.manual_definition21('LIMIT-81',81))$q$,'PT422','pós21: variable81 denied');
SELECT test.expect_error($q$SELECT private.templates_validate20(jsonb_set(test.manual_definition21(),'{variables,0,key}','"documento.Campo"'))$q$,'PT422','pós21: key grammar strict and matching exact');
SELECT test.expect_error($q$SELECT private.templates_validate20(jsonb_set(test.template_definition20(),'{variables,0,type}','"cpf"'))$q$,'PT422','pós21: automatic14 types immutable');
CREATE FUNCTION test.typed_definition21() RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT test.manual_definition21()||'{"content":"{{documento.nome}} {{documento.dia}} {{documento.preco}} {{documento.quantidade}} {{documento.cpf}} {{documento.cnpj}}","variables":[{"key":"documento.nome","label":"Nome manual","type":"text","required":true},{"key":"documento.dia","label":"Data manual","type":"date","required":true},{"key":"documento.preco","label":"Preço manual","type":"money","required":true},{"key":"documento.quantidade","label":"Quantidade manual","type":"number","required":true},{"key":"documento.cpf","label":"CPF manual","type":"cpf","required":true},{"key":"documento.cnpj","label":"CNPJ manual","type":"cnpj","required":true}]}'::jsonb;
$$;
SELECT test.assert_true(private.templates_validate20(test.typed_definition21())=test.typed_definition21(),'pós21: six custom types accepted');
-- A party may be a person or a company; this manual type never infers either from a customer.
CREATE FUNCTION test.tax_definition21() RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT test.manual_definition21()||'{"content":"{{documento.identificador}}","variables":[{"key":"documento.identificador","label":"CPF ou CNPJ","type":"tax_id","required":true}]}'::jsonb;$$;
SELECT test.assert_true(private.templates_validate20(test.tax_definition21())=test.tax_definition21(),'pós21: custom tax_id type accepted for PF or PJ');
CREATE FUNCTION test.tax_resolved21(p_value text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT private.documents_resolve21(test.tax_definition21(),jsonb_build_object('content',test.tax_definition21()->>'content','overrides',jsonb_build_object('documento.identificador',p_value),'money_in_words',false),'{}','[]');$$;
SELECT test.assert_true(test.tax_resolved21('52998224725')->'issues'='[]' AND test.tax_resolved21('52998224725')#>>'{values,documento.identificador}'='52998224725' AND test.tax_resolved21('52998224725')#>>'{formatted,documento.identificador}'='529.982.247-25','pós21: tax_id validates and formats CPF11');
SELECT test.assert_true(test.tax_resolved21('11222333000181')->'issues'='[]' AND test.tax_resolved21('11222333000181')#>>'{values,documento.identificador}'='11222333000181' AND test.tax_resolved21('11222333000181')#>>'{formatted,documento.identificador}'='11.222.333/0001-81','pós21: tax_id validates and formats CNPJ14');
SELECT test.assert_true(test.tax_resolved21('529.982.247-25')->'issues'='[]' AND test.tax_resolved21('11.222.333/0001-81')->'issues'='[]','pós21: tax_id canonical masks normalize to digits');
DO $$DECLARE raw text;BEGIN FOREACH raw IN ARRAY ARRAY['11111111111','11222333000182','529982247250','5299822472500','529.982247-25','11.222333/0001-81'] LOOP PERFORM test.assert_true(test.tax_resolved21(raw)->'issues' @> '[{"key":"documento.identificador","code":"invalid_value"}]','pós21: tax_id rejects checksum length and malformed mask');END LOOP;END$$;
SELECT test.assert_true(true,'pós21: tax_id rejects bad checksum12/13 digits and malformed masks');
CREATE FUNCTION test.manual_input21() RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT jsonb_build_object('content',test.typed_definition21()->>'content','overrides',jsonb_build_object('documento.nome',repeat('🙂',2000),'documento.dia','2028-02-29','documento.preco','123.45','documento.quantidade','1.250','documento.cpf','52998224725','documento.cnpj','11222333000181'),'money_in_words',true);$$;
SELECT private.documents_resolve21(test.typed_definition21(),test.manual_input21(),'{}','[]') AS manual_resolved21 \gset
SELECT test.assert_true(:'manual_resolved21'::jsonb->'issues'='[]' AND :'manual_resolved21'::jsonb#>>'{values,documento.cpf}'='52998224725' AND :'manual_resolved21'::jsonb#>>'{values,documento.cnpj}'='11222333000181' AND :'manual_resolved21'::jsonb#>>'{formatted,documento.cnpj}'='11.222.333/0001-81' AND :'manual_resolved21'::jsonb#>>'{formatted,documento.dia}'='29/02/2028' AND :'manual_resolved21'::jsonb#>>'{words,documento.preco}'='cento e vinte e três reais e quarenta e cinco centavos','pós21: Unicode2000 and six typed values format canonically');
SELECT test.expect_error($q$SELECT private.documents_input21(jsonb_set(test.manual_input21(),'{overrides,documento.nome}',to_jsonb(repeat('🙂',2001))),test.typed_definition21())$q$,'PT422','pós21: manual2001 Unicode denied');
SELECT test.expect_error($q$SELECT private.documents_input21(jsonb_set(test.manual_input21(),'{overrides,documento.unknown}','"x"'),test.typed_definition21())$q$,'PT422','pós21: undeclared override denied');
SELECT test.assert_true(private.documents_resolve21(test.template_definition20(),jsonb_build_object('content',test.template_definition20()->>'content','overrides',jsonb_build_object('cliente.nome',repeat('x',121)),'money_in_words',false),'{}','[]')->'issues' @> '[{"key":"cliente.nome","code":"invalid_value"}]' AND private.documents_resolve21(test.template_definition20(),jsonb_build_object('content',test.template_definition20()->>'content','overrides',jsonb_build_object('cliente.nome',repeat('x',500)),'money_in_words',false),'{}','[]')->'issues' @> '[{"key":"cliente.nome","code":"invalid_value"}]','pós21: legacy name121..500 remains readable with120 render limit');
SELECT test.expect_error($q$SELECT private.documents_input21(jsonb_build_object('content','{{cliente.nome}}','overrides',jsonb_build_object('cliente.nome',repeat('x',501)),'money_in_words',false),test.template_definition20())$q$,'PT422','pós21: automatic name override501 denied');
SELECT test.expect_error($q$SELECT private.documents_input21(jsonb_build_object('content','{{cliente.endereco}}','overrides',jsonb_build_object('cliente.endereco',repeat('x',501)),'money_in_words',false),test.template_definition20()||'{"variables":[{"key":"cliente.endereco","label":"Endereço","type":"text","required":false}]}')$q$,'PT422','pós21: automatic text500 preserved');
SELECT test.assert_true(private.documents_resolve21(test.typed_definition21(),jsonb_set(test.manual_input21(),'{overrides,documento.cpf}','"11111111111"'),'{}','[]')->'issues' @> '[{"key":"documento.cpf","code":"invalid_value"}]' AND private.documents_resolve21(test.typed_definition21(),jsonb_set(test.manual_input21(),'{overrides,documento.cnpj}','"11222333000182"'),'{}','[]')->'issues' @> '[{"key":"documento.cnpj","code":"invalid_value"}]','pós21: both checksum failures remain pending');
SELECT test.assert_true(private.documents_resolve21(test.typed_definition21(),test.manual_input21()||'{"content":"Texto removido"}','{}','[]')->'issues' @> '[{"key":"documento.nome","code":"missing_placeholder"}]','pós21: required manual placeholder removal blocks preparation');
SELECT test.assert_true(private.documents_resolve21(test.typed_definition21(),test.manual_input21()||'{"overrides":{}}','{}','[]')->'issues' @> '[{"key":"documento.cpf","code":"required"}]','pós21: custom CPF never inferred from any person');
SELECT test.assert_true(private.documents_resolve21(test.manual_definition21(),jsonb_build_object('content',repeat('{{documento.campo_1}}',26),'overrides',jsonb_build_object('documento.campo_1',repeat('x',2000)),'money_in_words',false),'{}','[]')->'issues' @> '[{"key":"content","code":"invalid_value"}]','pós21: rendered50000 ceiling preserved');
SELECT test.assert_true((SELECT relrowsecurity FROM pg_class WHERE oid='private.template_import_batches'::regclass) AND NOT EXISTS(SELECT FROM unnest(ARRAY['anon','authenticated','service_role'])r WHERE has_table_privilege(r,'private.template_import_batches','SELECT,INSERT,UPDATE,DELETE') OR has_function_privilege(r,'private.import_template_drafts(uuid,text,text,jsonb)','EXECUTE')) AND NOT(SELECT prosecdef FROM pg_proc WHERE oid='private.import_template_drafts(uuid,text,text,jsonb)'::regprocedure),'pós21: import invoker and RLS/ACL closed to API roles');
CREATE TABLE test.manual_before21 AS SELECT 'document' kind,count(*) n FROM public.documents UNION ALL SELECT 'approval',count(*) FROM private.template_approvals UNION ALL SELECT 'report',count(*) FROM private.audit_reports;
SET ROLE migrator;
SELECT test.assert_true(NOT(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user),'pós21: import executes with limited migrator');
SELECT private.import_template_drafts('00000000-0000-4000-e000-000000000201','manual-test','https://drive.google.com/drive/folders/generic-local',jsonb_build_array(test.manual_definition21())) AS batch21 \gset
SELECT test.assert_true(private.import_template_drafts('00000000-0000-4000-e000-000000000201','manual-test','https://drive.google.com/drive/folders/generic-local',jsonb_build_array(test.manual_definition21()))=:'batch21'::jsonb,'pós21: exact batch replay returns persisted summary');
SELECT test.expect_error($q$SELECT private.import_template_drafts('00000000-0000-4000-e000-000000000201','manual-test','https://drive.google.com/drive/folders/other',jsonb_build_array(test.manual_definition21()))$q$,'PT409','pós21: same key different source/hash conflicts');
SELECT test.expect_error($q$SELECT private.import_template_drafts('00000000-0000-4000-e000-000000000201','rollback-test','https://drive.google.com/drive/folders/generic-local',jsonb_build_array(test.manual_definition21('ROLLBACK-TEST'),test.manual_definition21()))$q$,'PT409','pós21: existing code conflicts atomically');
SELECT test.expect_error($q$SELECT private.import_template_drafts('00000000-0000-4000-e000-000000000201','invalid-test','https://drive.google.com/drive/folders/generic-local',jsonb_build_array(test.manual_definition21('ROLLBACK-INVALID'),test.manual_definition21('INVALID-TEST')||'{"variables":[]}'))$q$,'PT422','pós21: invalid last definition reverts entire batch');
RESET ROLE;
SELECT test.assert_true(NOT EXISTS(SELECT FROM public.templates WHERE code IN('ROLLBACK-TEST','ROLLBACK-INVALID')) AND (SELECT count(*)=1 FROM private.template_import_batches WHERE batch_key IN('manual-test','rollback-test','invalid-test')),'pós21: failed imports leave no partial draft or batch');
SELECT test.assert_true((SELECT created_by IS NULL AND source_import_id=(:'batch21'::jsonb->>'id')::uuid FROM public.templates WHERE code='IMPORT-TEST') AND(SELECT v.created_by IS NULL AND v.source_import_id=t.source_import_id AND private.template_version20(v)->>'source_import_id'=t.source_import_id::text FROM public.template_versions v JOIN public.templates t ON t.office_id=v.office_id AND t.id=v.template_id WHERE t.code='IMPORT-TEST'),'pós21: technical template/version authorship has source UUID in DTO');
SELECT test.assert_true((SELECT count(*)=1 AND bool_and(actor_kind='operator' AND actor_id IS NULL AND actor_db_role='migrator' AND changes='{}') FROM public.audit_events WHERE target_id=(:'batch21'::jsonb#>>'{items,0,id}')::uuid AND action='templates.saved'),'pós21: operator audit records real DB role without content');
SELECT test.assert_true((SELECT count(*) FROM public.documents)=(SELECT n FROM test.manual_before21 WHERE kind='document') AND(SELECT count(*) FROM private.template_approvals)=(SELECT n FROM test.manual_before21 WHERE kind='approval') AND(SELECT count(*) FROM private.audit_reports)=(SELECT n FROM test.manual_before21 WHERE kind='report'),'pós21: import never creates document PDF or approval');
SELECT test.expect_error($q$INSERT INTO public.templates(office_id,code,latest_version)VALUES('00000000-0000-4000-e000-000000000201','NO-AUTHOR',1)$q$,'23514','pós21: null creator requires import provenance');
SELECT test.expect_error(format('INSERT INTO public.templates(office_id,code,latest_version,created_by,source_import_id)VALUES(%L,%L,1,%L,%L)','00000000-0000-4000-e000-000000000201','FAKE-HUMAN','00000000-0000-4000-a000-000000000201',:'batch21'::jsonb->>'id'),'23514','pós21: human creator cannot impersonate technical provenance');
SELECT test.expect_error(format('INSERT INTO public.templates(office_id,code,latest_version,source_import_id)VALUES(%L,%L,1,%L)','00000000-0000-4000-e000-000000000202','WRONG-OFFICE',:'batch21'::jsonb->>'id'),'23503','pós21: composite import FK isolates offices');
SELECT test.expect_error(format('UPDATE private.template_import_batches SET batch_key=%L WHERE id=%L','changed',:'batch21'::jsonb->>'id'),'PT409','pós21: batch evidence immutable');
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000201","session_id":"00000000-0000-4000-c000-000000000201"}';
SELECT test.expect_error($q$SELECT private.import_template_drafts('00000000-0000-4000-e000-000000000201','api-test','https://example.test',jsonb_build_array(test.manual_definition21()))$q$,'42501','pós21: authenticated import denied');
SELECT test.assert_true(public.templates_page('00000000-0000-4000-e000-000000000201','IMPORT-TEST',1,5)->'items'->0->'current_version'='null' AND public.document_options('00000000-0000-4000-e000-000000000201','templates',NULL,'IMPORT-TEST',1)->>'total'='0','pós21: draft remains in20 review and absent from21 selection');
SELECT public.template_approve('00000000-0000-4000-e000-000000000201',(:'batch21'::jsonb#>>'{items,0,id}')::uuid,(:'batch21'::jsonb#>>'{items,0,version_id}')::uuid,1,'Revisão humana local explícita',gen_random_uuid()) AS approved_import21 \gset
SELECT test.assert_true(:'approved_import21'::jsonb->'versions'->0->>'created_by' IS NULL AND :'approved_import21'::jsonb->'versions'->0->>'approved_by'='00000000-0000-4000-a000-000000000201' AND public.document_options('00000000-0000-4000-e000-000000000201','templates',NULL,'IMPORT-TEST',1)->>'total'='1','pós21: human20 approval is explicit and unlocks21 discovery');
SELECT public.template_save('00000000-0000-4000-e000-000000000201',(:'batch21'::jsonb#>>'{items,0,id}')::uuid,test.manual_definition21(),1,'Nova versão humana local',gen_random_uuid()) AS human_after21 \gset
SELECT test.assert_true(:'human_after21'::jsonb->'versions'->0->>'created_by'='00000000-0000-4000-a000-000000000201' AND :'human_after21'::jsonb->'versions'->0->'source_import_id'='null' AND :'human_after21'::jsonb->'versions'->0->'approved_at'='null' AND :'human_after21'::jsonb->'versions'->1->>'source_import_id'=:'batch21'::jsonb->>'id','pós21: next human version has real author no import or inherited approval');
RESET ROLE;
SET ROLE migrator;
SELECT test.assert_true(private.import_template_drafts('00000000-0000-4000-e000-000000000201','manual-test','https://drive.google.com/drive/folders/generic-local',jsonb_build_array(test.manual_definition21()))=:'batch21'::jsonb,'pós21: replay stays exact after human edit and approval');
RESET ROLE;
SELECT private.documents_input21(jsonb_build_object('content',test.manual_definition21('EIGHTY',80)->>'content','overrides',(SELECT jsonb_object_agg('documento.campo_'||n,'valor') FROM generate_series(1,80)n),'money_in_words',false),test.manual_definition21('EIGHTY',80));
SELECT test.assert_true(true,'pós21: exactly80 declared overrides accepted');
SELECT test.expect_error($q$SELECT private.documents_input21(jsonb_build_object('content','texto','overrides',(SELECT jsonb_object_agg('documento.campo_'||n,'valor') FROM generate_series(1,81)n),'money_in_words',false),test.manual_definition21('EIGHTYONE',81))$q$,'PT422','pós21: override81 denied');
SELECT test.assert_true(private.templates_validate20(test.manual_definition21()||jsonb_build_object('content','{{documento.'||repeat('a',64)||'}}','variables',jsonb_build_array(jsonb_build_object('key','documento.'||repeat('a',64),'label','Limite de chave','type','text','required',false)))) IS NOT NULL,'pós21: manual suffix64 accepted');
SELECT test.expect_error($q$SELECT private.templates_validate20(test.manual_definition21()||jsonb_build_object('content','{{documento.'||repeat('a',65)||'}}','variables',jsonb_build_array(jsonb_build_object('key','documento.'||repeat('a',65),'label','Chave longa','type','text','required',false))))$q$,'PT422','pós21: manual suffix65 denied');
SELECT test.assert_true(NOT EXISTS(SELECT FROM pg_constraint fk WHERE fk.contype='f' AND fk.conrelid IN('private.template_import_batches'::regclass,'public.templates'::regclass,'public.template_versions'::regclass) AND NOT EXISTS(SELECT FROM pg_index ix WHERE ix.indrelid=fk.conrelid AND ix.indisvalid AND ix.indpred IS NULL AND ix.indexprs IS NULL AND(ix.indkey::smallint[])[0:cardinality(fk.conkey)-1] @> fk.conkey)),'pós21: import provenance FKs have covering indexes');
SET ROLE anon;
SELECT test.expect_error($q$SELECT private.import_template_drafts(NULL,NULL,NULL,NULL)$q$,'42501','pós21: anonymous import call denied');
RESET ROLE;
SET ROLE service_role;
SELECT test.expect_error($q$SELECT private.import_template_drafts(NULL,NULL,NULL,NULL)$q$,'42501','pós21: service-role import call denied');
RESET ROLE;
-- Full local browser/API-shaped RPC flow. Rollback keeps old race fixtures exact.
BEGIN;
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000201","session_id":"00000000-0000-4000-c000-000000000201"}';
SELECT public.document_operate('00000000-0000-4000-e000-000000000201',(SELECT document_id FROM test.documents_fixture21),jsonb_build_object('kind','save','expected_revision',4,'input',jsonb_build_object('content',test.template_definition20()->>'content','overrides',jsonb_build_object('cliente.nome',repeat('x',500)),'money_in_words',false),'idempotency_key',gen_random_uuid())) AS legacy_name21 \gset
SELECT test.assert_true(public.document_detail('00000000-0000-4000-e000-000000000201',(SELECT document_id FROM test.documents_fixture21),5,1)->'issues' @> '[{"key":"cliente.nome","code":"invalid_value"}]' AND NOT(:'legacy_name21'::jsonb->>'can_prepare')::boolean,'pós21: historical name500 reopens through detail with explicit issue');
SELECT test.expect_error(format('SELECT public.document_operate(%L,%L,%L)','00000000-0000-4000-e000-000000000201',(SELECT document_id FROM test.documents_fixture21),jsonb_build_object('kind','prepare','expected_revision',5,'idempotency_key',gen_random_uuid())),'PT422','pós21: legacy name500 still blocks actual prepare');
SELECT public.template_save('00000000-0000-4000-e000-000000000201',NULL,test.typed_definition21()||'{"code":"CUSTOM-FLOW-LOCAL"}',0,'Definição tipada local',gen_random_uuid()) AS typed_template21 \gset
SELECT public.template_approve('00000000-0000-4000-e000-000000000201',(:'typed_template21'::jsonb->>'id')::uuid,(:'typed_template21'::jsonb#>>'{versions,0,id}')::uuid,1,'Aprovação explícita local',gen_random_uuid()) AS typed_approved21 \gset
SELECT public.document_create('00000000-0000-4000-e000-000000000201',(SELECT request_id FROM test.documents_fixture21),(SELECT (public.document_detail('00000000-0000-4000-e000-000000000201',(SELECT document_id FROM test.documents_fixture21),NULL,1)->>'request_item_id')::uuid),(:'typed_template21'::jsonb#>>'{versions,0,id}')::uuid,'[]',gen_random_uuid()) AS typed_doc21 \gset
SELECT test.assert_true((:'typed_doc21'::jsonb->>'can_prepare')::boolean=false AND :'typed_doc21'::jsonb->'issues' @> '[{"key":"documento.cpf","code":"required"}]','pós21: new document awaits all manual fields');
SELECT public.document_operate('00000000-0000-4000-e000-000000000201',(:'typed_doc21'::jsonb->>'id')::uuid,jsonb_build_object('kind','save','expected_revision',1,'input',jsonb_set(test.manual_input21(),'{overrides,documento.cnpj}','"11222333000182"'),'idempotency_key',gen_random_uuid())) AS invalid_cnpj_doc21 \gset
SELECT test.expect_error(format('SELECT public.document_operate(%L,%L,%L)','00000000-0000-4000-e000-000000000201',:'typed_doc21'::jsonb->>'id',jsonb_build_object('kind','prepare','expected_revision',2,'idempotency_key',gen_random_uuid())),'PT422','pós21: invalid CNPJ blocks actual prepare RPC');
SELECT public.document_operate('00000000-0000-4000-e000-000000000201',(:'typed_doc21'::jsonb->>'id')::uuid,jsonb_build_object('kind','save','expected_revision',2,'input',test.manual_input21()||'{"content":"Campo obrigatório removido"}','idempotency_key',gen_random_uuid())) AS missing_doc21 \gset
SELECT test.expect_error(format('SELECT public.document_operate(%L,%L,%L)','00000000-0000-4000-e000-000000000201',:'typed_doc21'::jsonb->>'id',jsonb_build_object('kind','prepare','expected_revision',3,'idempotency_key',gen_random_uuid())),'PT422','pós21: missing manual placeholder blocks actual prepare RPC');
SELECT public.document_operate('00000000-0000-4000-e000-000000000201',(:'typed_doc21'::jsonb->>'id')::uuid,jsonb_build_object('kind','save','expected_revision',3,'input',test.manual_input21(),'idempotency_key',gen_random_uuid())) AS complete_doc21 \gset
SELECT test.assert_true(public.document_operate('00000000-0000-4000-e000-000000000201',(:'typed_doc21'::jsonb->>'id')::uuid,jsonb_build_object('kind','prepare','expected_revision',4,'idempotency_key',gen_random_uuid()))->>'status'='prepared','pós21: all six manual types permit preparation when complete');
RESET ROLE;
ROLLBACK;
